pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // The reference implementation returns true when interfaceId matches
        // type(IERC1155).interfaceId OR type(IERC1155MetadataURI).interfaceId OR super.supportsInterface(interfaceId).
        // The buggy version (AND instead of OR) returns false unless it matches ALL three.
        // The rule: a call to supportsInterface must not revert, and must return true exactly when
        // any single condition is satisfied.
        bool hasERC165 = interfaceId == 0x01ffc9a7; // type(IERC165).interfaceId
        bool has1155 = interfaceId == 0xd9b67a26;   // type(IERC1155).interfaceId
        bool hasMeta = interfaceId == 0x0e89341c;   // type(IERC1155MetadataURI).interfaceId

        // For the reference contract, the result is true if *any* of the three holds.
        bool expected = hasERC165 || has1155 || hasMeta;

        // Call the actual implementation (which we compile from the source under test).
        bool actual = c.supportsInterface(interfaceId);

        // This assertion holds for the reference (OR version) for every interfaceId,
        // but fails on the AND version for any interfaceId that satisfies only one or two
        // of the conditions (e.g. a genuine IERC1155 id without the metadata bit).
        assertEq(actual, expected);
    }
}

